create role anon;create role authenticated;create role service_role;
create table public.score_tracker_users(id uuid primary key,username text,session_token_hash text,session_expires_at timestamptz,exam_category_label text,exam_category_options jsonb,participant_defaults jsonb not null default '{}');
create table public.score_tracker_exam_modules("exam_id" uuid not null,"user_id" uuid not null,"module_id" uuid not null,"sort_order" integer default 1 not null,"created_at" timestamptz default now() not null,"ranks" jsonb, primary key(exam_id,module_id));
create table public.score_tracker_exams("id" uuid default gen_random_uuid() not null,"user_id" uuid not null,"name" text not null,"exam_date" date not null,"created_at" timestamptz default now() not null,"updated_at" timestamptz default now() not null,"total_rank" integer,"total_participants" integer,"is_hidden" boolean default false not null,"grade_level" text,"total_class_rank" integer,"total_class_participants" integer,"total_year_position_percent" numeric,"total_class_position_percent" numeric,"total_actual_score" numeric,"total_raw_score" numeric,"city_rank" integer,"city_participants" integer,"district_rank" integer,"district_participants" integer,"end_date" date,"averages" jsonb default '{}'::jsonb not null,"reflection" text default ''::text not null,"reflection_revision" integer default 0 not null,"reflection_updated_at" timestamptz,"question_type_scores" jsonb default '{}'::jsonb not null, primary key(id));
create table public.score_tracker_modules("id" uuid default gen_random_uuid() not null,"user_id" uuid not null,"name" text not null,"subjects" jsonb default '[]'::jsonb not null,"is_builtin" boolean default false not null,"sort_order" integer default 1 not null,"created_at" timestamptz default now() not null,"updated_at" timestamptz default now() not null, primary key(id));
create table public.score_tracker_scores("id" uuid default gen_random_uuid() not null,"exam_id" uuid not null,"user_id" uuid not null,"subject" text not null,"target_score" numeric,"actual_score" numeric,"max_score" numeric default 100 not null,"created_at" timestamptz default now() not null,"updated_at" timestamptz default now() not null,"rank_position" integer,"participant_count" integer,"raw_score" numeric,"raw_max_score" numeric default 100,"class_rank_position" integer,"class_participant_count" integer,"year_position_percent" numeric,"class_position_percent" numeric,"exclude_from_total" boolean default false not null, primary key(id));
create table public.score_tracker_subjects("id" uuid default gen_random_uuid() not null,"user_id" uuid not null,"name" text not null,"default_max" numeric default 100 not null,"sort_order" integer default 0 not null,"created_at" timestamptz default now() not null,"updated_at" timestamptz default now() not null, primary key(id));
create table public.score_tracker_user_goals("user_id" uuid not null,"subject_goals" jsonb default '{}'::jsonb not null,"total_goal" numeric,"dream_school" text,"exam_date" date,"date_name" text,"updated_at" timestamptz default now() not null, primary key(user_id));
alter table score_tracker_modules add unique(user_id,name);alter table score_tracker_subjects add unique(user_id,name);
alter table public.score_tracker_exam_modules add constraint score_tracker_exam_modules_sort_order_check CHECK (((sort_order >= 1) AND (sort_order <= 50)));
alter table public.score_tracker_exams add constraint score_tracker_exams_averages_check CHECK ((jsonb_typeof(averages) = 'object'::text));
alter table public.score_tracker_exams add constraint score_tracker_exams_date_range_check CHECK (((end_date IS NULL) OR (end_date >= exam_date)));
alter table public.score_tracker_exams add constraint score_tracker_exams_grade_level_check CHECK (((grade_level IS NULL) OR ((char_length(btrim(grade_level)) >= 1) AND (char_length(btrim(grade_level)) <= 20))));
alter table public.score_tracker_exams add constraint score_tracker_exams_question_type_scores_check CHECK (((jsonb_typeof(question_type_scores) = 'object'::text) AND (octet_length((question_type_scores)::text) <= 240000)));
alter table public.score_tracker_exams add constraint score_tracker_exams_reflection_check CHECK ((char_length(reflection) <= 10000));
alter table public.score_tracker_exams add constraint score_tracker_exams_reflection_revision_check CHECK ((reflection_revision >= 0));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_actual_score_check CHECK (((total_actual_score IS NULL) OR ((total_actual_score >= (0)::numeric) AND (total_actual_score <= (99999)::numeric))));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_class_participants_check CHECK (((total_class_participants IS NULL) OR (total_class_participants >= 1)));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_class_position_percent_check CHECK (((total_class_position_percent IS NULL) OR ((total_class_position_percent >= (0)::numeric) AND (total_class_position_percent <= (100)::numeric))));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_class_rank_bounds_check CHECK (((total_class_rank IS NULL) OR (total_class_participants IS NULL) OR (total_class_rank <= total_class_participants)));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_class_rank_check CHECK (((total_class_rank IS NULL) OR (total_class_rank >= 1)));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_rank_check CHECK ((((total_rank IS NULL) OR (total_rank >= 1)) AND ((total_participants IS NULL) OR (total_participants >= 1)) AND ((total_rank IS NULL) OR (total_participants IS NULL) OR (total_rank <= total_participants))));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_raw_score_check CHECK (((total_raw_score IS NULL) OR ((total_raw_score >= (0)::numeric) AND (total_raw_score <= (99999)::numeric))));
alter table public.score_tracker_exams add constraint score_tracker_exams_total_year_position_percent_check CHECK (((total_year_position_percent IS NULL) OR ((total_year_position_percent >= (0)::numeric) AND (total_year_position_percent <= (100)::numeric))));
alter table public.score_tracker_modules add constraint score_tracker_modules_name_check CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 30)));
alter table public.score_tracker_modules add constraint score_tracker_modules_subjects_array_check CHECK ((jsonb_typeof(subjects) = 'array'::text));
alter table public.score_tracker_scores add constraint score_tracker_scores_class_participants_check CHECK (((class_participant_count IS NULL) OR (class_participant_count >= 1)));
alter table public.score_tracker_scores add constraint score_tracker_scores_class_position_percent_check CHECK (((class_position_percent IS NULL) OR ((class_position_percent >= (0)::numeric) AND (class_position_percent <= (100)::numeric))));
alter table public.score_tracker_scores add constraint score_tracker_scores_class_rank_bounds_check CHECK (((class_rank_position IS NULL) OR (class_participant_count IS NULL) OR (class_rank_position <= class_participant_count)));
alter table public.score_tracker_scores add constraint score_tracker_scores_class_rank_check CHECK (((class_rank_position IS NULL) OR (class_rank_position >= 1)));
alter table public.score_tracker_scores add constraint score_tracker_scores_rank_check CHECK ((((rank_position IS NULL) OR (rank_position >= 1)) AND ((participant_count IS NULL) OR (participant_count >= 1)) AND ((rank_position IS NULL) OR (participant_count IS NULL) OR (rank_position <= participant_count))));
alter table public.score_tracker_scores add constraint score_tracker_scores_raw_max_score_check CHECK (((raw_max_score IS NULL) OR (raw_max_score > (0)::numeric)));
alter table public.score_tracker_scores add constraint score_tracker_scores_raw_score_check CHECK (((raw_score IS NULL) OR ((raw_score >= (0)::numeric) AND (raw_score <= (9999)::numeric))));
alter table public.score_tracker_scores add constraint score_tracker_scores_subject_name_check CHECK (((char_length(btrim(subject)) >= 1) AND (char_length(btrim(subject)) <= 40)));
alter table public.score_tracker_scores add constraint score_tracker_scores_year_position_percent_check CHECK (((year_position_percent IS NULL) OR ((year_position_percent >= (0)::numeric) AND (year_position_percent <= (100)::numeric))));
alter table public.score_tracker_subjects add constraint score_tracker_subjects_default_max_check CHECK (((default_max > (0)::numeric) AND (default_max <= (999)::numeric)));
alter table public.score_tracker_subjects add constraint score_tracker_subjects_name_check CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 40)));
